//!
//! This module stores sparse-vector posting lists in a single blockfile keyed
//! by `(prefix: String, key: u32)` with [`SparsePostingBlock`] values, and
//! serves top-k dot-product queries over them.
//!
//! # Storage layout
//!
//! For a dimension `dim` with encoded key `e = encode_u32(dim)`:
//!
//! - **Data blocks**: prefix `e`, keys `0, 1, 2, …`. Each value is a
//!   [`SparsePostingBlock`] holding a contiguous, offset-sorted chunk of the
//!   dimension's `(offset, weight)` entries. A dimension is split across
//!   several data blocks when its entries would exceed the configured block
//!   size in bytes (see [`MaxScoreWriter::with_block_size`]).
//! - **Directory parts**: prefix `DIRECTORY_PREFIX + e`, keys `0, 1, 2, …`.
//!   Only written for dimensions with *more than one* data block. Each part is
//!   a directory-tagged [`SparsePostingBlock`] recording the per-block
//!   `(max_offset, max_weight)` pairs so the reader can reconstruct a
//!   [`Directory`]. `DIRECTORY_PREFIX` (`"~"`) sorts after every base64 data
//!   prefix, keeping directory parts grouped at the end of the keyspace.
//!
//! # Query
//!
//! Queries accumulate exact dot products over a sliding window of document
//! offsets using [`PostingCursor::drain_essential`], guaranteeing perfect
//! recall (modulo f16 weight quantization).

use std::collections::{BTreeSet, BinaryHeap};

use chroma_blockstore::{BlockfileFlusher, BlockfileReader, BlockfileWriter};
use chroma_error::{ChromaError, ErrorCodes};
use chroma_types::{
    Directory, DirectoryBlock, SignedRoaringBitmap, SparsePostingBlock, SparsePostingBlockError,
    DIRECTORY_PREFIX, MAX_BLOCK_ENTRIES,
};
use dashmap::DashMap;
use std::sync::Arc;
use thiserror::Error;
use uuid::Uuid;

use crate::sparse::types::{decode_u32, encode_u32, Score};

/// Default maximum size in bytes for a single posting block. Used when
/// creating blockfile writers for the sparse posting list.
pub const SPARSE_POSTING_BLOCK_SIZE_BYTES: usize = 65536;

/// Number of document offsets processed per query accumulation window. The
/// flat bitmap passed to [`PostingCursor::drain_essential`] is `[u64; 64]`
/// (4096 bits), so the window may not exceed 4096 offsets.
const QUERY_WINDOW: u32 = 4096;

#[derive(Debug, Error)]
pub enum SparseMaxScoreError {
    #[error(transparent)]
    Blockfile(#[from] Box<dyn ChromaError>),
    #[error(transparent)]
    Block(#[from] SparsePostingBlockError),
}

impl ChromaError for SparseMaxScoreError {
    fn code(&self) -> ErrorCodes {
        match self {
            SparseMaxScoreError::Blockfile(err) => err.code(),
            SparseMaxScoreError::Block(_) => ErrorCodes::Internal,
        }
    }
}

// ── PostingCursor ────────────────────────────────────────────────────

/// A cursor over the decoded posting entries of a single dimension.
///
/// The entries are materialized (decoded) up front into offset-sorted parallel
/// vectors, so lookups within a window use binary search. `advance`/`next`
/// provide a forward-only iterator used by cursor-based query evaluation, while
/// `window_upper_bound`, `get_value`, `drain_essential`, and `score_candidates`
/// are position-independent range operations.
pub struct PostingCursor {
    offsets: Vec<u32>,
    values: Vec<f32>,
    pos: usize,
}

impl PostingCursor {
    /// Build a cursor from a dimension's data blocks (in block order).
    pub fn from_blocks(mut blocks: Vec<SparsePostingBlock>) -> Self {
        let total: usize = blocks.iter().map(|b| b.len()).sum();
        let mut offsets = Vec::with_capacity(total);
        let mut values = Vec::with_capacity(total);
        for block in &mut blocks {
            let (o, v) = block.decode();
            offsets.extend_from_slice(o);
            values.extend_from_slice(v);
        }
        Self {
            offsets,
            values,
            pos: 0,
        }
    }

    /// The `(min_offset, max_offset)` span of this cursor, or `None` if empty.
    pub fn offset_span(&self) -> Option<(u32, u32)> {
        match (self.offsets.first(), self.offsets.last()) {
            (Some(&lo), Some(&hi)) => Some((lo, hi)),
            _ => None,
        }
    }

    /// Half-open index range `[start, end)` covering entries whose offset lies
    /// within the inclusive offset window `[lo, hi]`.
    fn window_indices(&self, lo: u32, hi: u32) -> (usize, usize) {
        let start = self.offsets.partition_point(|&o| o < lo);
        let end = self.offsets.partition_point(|&o| o <= hi);
        (start, end)
    }

    /// Return the first `(offset, weight)` at or after the current position
    /// with `offset >= target` that passes `mask`, positioning the cursor on
    /// it. Entries that fail the mask or precede `target` are skipped. Returns
    /// `None` once the cursor is exhausted.
    pub fn advance(&mut self, target: u32, mask: &SignedRoaringBitmap) -> Option<(u32, f32)> {
        while self.pos < self.offsets.len() {
            let offset = self.offsets[self.pos];
            if offset >= target && mask.contains(offset) {
                return Some((offset, self.values[self.pos]));
            }
            self.pos += 1;
        }
        None
    }

    /// Move past the entry the cursor currently rests on.
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) {
        if self.pos < self.offsets.len() {
            self.pos += 1;
        }
    }

    /// Maximum weight across all entries with offset in `[lo, hi]` (inclusive),
    /// or `0.0` when the window contains no entries.
    pub fn window_upper_bound(&self, lo: u32, hi: u32) -> f32 {
        let (start, end) = self.window_indices(lo, hi);
        self.values[start..end].iter().copied().fold(0.0f32, f32::max)
    }

